// import { formatedatetime } from "@/JsonFiles/DateFormate.js";
import OverlayComp from "@/components/OverlayComp.vue";
import { mapGetters } from "vuex";
import NotificationList from "@/components/NotificationList.vue";
import { format } from "date-fns";
import { get_all_users } from "@/mixins/GetAllUsers.js";
import { formatedatetime } from "@/JsonFiles/DateFormate.js";
export default {
  components: {
    OverlayComp,
    NotificationList
  },
  props: {
    notificationsData: Array,
    chatList: {
      type: Array,
      default: () => [] // set a default value here if needed
    },
    channelDataProp: {
      type: Array,
      default: () => []
    },
    messageDataProp: {
      type: Array,
      default: () => []
    }
  },
  data() {
    return {
      pendingCount: "",
      submittedWorkflowsCount: 0,
      participatedWorkflowsCount: 0,
      myteamCount: "",
      overlay: false,
      listItems: [],
      storednotifications: [],
      tableData: [],
      tableLoading: false,
      componentCheck: 0,
      notificationTab: false,
      tasksTab: null,
      headers: [{
        text: "Initiated By",
        value: "body.data.msg_sent_by",
        sortable: false
      },
      // { text: "User", value: "form_unique_type", sortable: false },
      {
        text: "Initiated On",
        value: "body.data.msg_created_on",
        sortable: false
      }, {
        text: "Message",
        value: "messageTitle",
        sortable: false
      }],
      windowHeight: 0,
      lastNotification: null,
      // Channel related data
      selectedChannel: null
    };
  },
  async created() {
    await this.get_all_users();
